1	//nolint:ireturn // bubbletea model methods in this file must return framework interfaces
2	package summarytui
3	
4	import (
5		"context"
6		"fmt"
7		"strconv"
8		"strings"
9	
10		"github.com/charmbracelet/bubbles/key"
11		"github.com/charmbracelet/bubbles/paginator"
12		"github.com/charmbracelet/bubbles/table"
13		tea "github.com/charmbracelet/bubbletea"
14		"github.com/entireio/cli/cmd/entire/cli/insightsdb"
15	)
16	
17	const defaultPageSize = 10
18	const rootVerticalChrome = 6
19	
20	type branchFilter int
21	
22	const (
23		filterCurrentBranch branchFilter = iota
24		filterMainBranch
25		filterAllBranches
26	)
27	
28	//nolint:recvcheck // bubbletea pattern: value receiver for interface, pointer receivers for mutation helpers
29	type rootModel struct {
30		ctx           context.Context
31		rows          []insightsdb.SessionRow
32		filteredRows  []insightsdb.SessionRow
33		currentBranch string
34		filter        branchFilter
35		table         table.Model
36		paginator     paginator.Model
37		pageSize      int
38		width         int
39		height        int
40		styles        styles
41		detailPage    *detailModel
42	}
43	
44	type openDetailMsg struct {
45		row insightsdb.SessionRow
46	}
47	
48	type closeDetailMsg struct{}
49	
50	func Run(ctx context.Context, rows []insightsdb.SessionRow) error {
51		return RunWithCurrentBranch(ctx, rows, "")
52	}
53	
54	func RunWithCurrentBranch(_ context.Context, rows []insightsdb.SessionRow, currentBranch string) error {
55		p := tea.NewProgram(newRootModel(rows, currentBranch), tea.WithAltScreen())
56		_, err := p.Run()
57		if err != nil {
58			return fmt.Errorf("run summary TUI: %w", err)
59		}
60		return nil
61	}
62	
63	func newRootModel(rows []insightsdb.SessionRow, currentBranch string) rootModel {
64		columns := []table.Column{
65			{Title: "TIME", Width: 16},
66			{Title: "AGENT", Width: 14},
67			{Title: "BRANCH", Width: 24},
68			{Title: "CHECKPOINT", Width: 12},
69			{Title: "SUMMARY", Width: 8},
70			{Title: "FACETS", Width: 7},
71			{Title: "TOKENS", Width: 8},
72			{Title: "TURNS", Width: 5},
73		}
74		styles := newStyles()
75		t := table.New(table.WithColumns(columns), table.WithFocused(true))
76		t.SetStyles(styles.tableStyles())
77		p := paginator.New()
78		p.PerPage = defaultPageSize
79		m := rootModel{
80			ctx:           context.Background(),
81			rows:          append([]insightsdb.SessionRow(nil), rows...),
82			currentBranch: currentBranch,
83			filter:        filterCurrentBranch,
84			table:         t,
85			paginator:     p,
86			pageSize:      defaultPageSize,
87			styles:        styles,
88			width:         100,
89			height:        30,
90		}
91		m.rebuildFilteredRows()
92		return m
93	}
94	
95	func (m rootModel) Init() tea.Cmd {
96		return nil
97	}
98	
99	//nolint:ireturn // required by bubbletea Model interface
100	func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
101		switch msg := msg.(type) {
102		case tea.WindowSizeMsg:
103			m.resize(msg.Width, msg.Height)
104			if m.detailPage != nil {
105				m.detailPage.setSize(m.width, m.height)
106			}
107			return m, nil
108	
109		case tea.KeyMsg:
110			if m.detailPage != nil {
111				//nolint:exhaustive // only quit/back keys are handled here; all others delegate to the viewport
112				switch msg.Type {
113				case tea.KeyEsc:
114					return m, func() tea.Msg { return closeDetailMsg{} }
115				case tea.KeyCtrlC:
116					return m, tea.Quit
117				default:
118				}
119				var cmd tea.Cmd
120				*m.detailPage, cmd = m.detailPage.update(msg)
121				return m, cmd
122			}
123	
124			switch {
125			case key.Matches(msg, keys.cycleFilter):
126				m.cycleFilter()
127				return m, nil
128			case key.Matches(msg, keys.nextPage):
129				m.nextPage()
130				return m, nil
131			case key.Matches(msg, keys.prevPage):
132				m.prevPage()
133				return m, nil
134			}
135	
136			//nolint:exhaustive // only command-specific keys are handled here; all others fall through to the table widget
137			switch msg.Type {
138			case tea.KeyEnter:
139				if row := m.selectedRow(); row != nil {
140					selected := *row
141					return m, func() tea.Msg { return openDetailMsg{row: selected} }
142				}
143			case tea.KeyCtrlC:
144				return m, tea.Quit
145			default:
146			}
147	
148		case openDetailMsg:
149			m.detailPage = newDetailModel(m.styles, msg.row)
150			m.detailPage.setSize(m.width, m.height)
151			return m, nil
152	
153		case closeDetailMsg:
154			m.detailPage = nil
155			return m, nil
156		}
157	
158		var cmd tea.Cmd
159		m.table, cmd = m.table.Update(msg)
160		return m, cmd
161	}
162	
163	func (m rootModel) View() string {
164		if m.detailPage != nil {
165			return m.detailPage.view()
166		}
167	
168		var b strings.Builder
169		b.WriteString(m.styles.render(m.styles.appTitle, "SESSION SUMMARY"))
170		b.WriteString("\n\n")
171		b.WriteString(renderFilterChips(m.styles, m.filter))
172		b.WriteString("  ")
173		b.WriteString(m.styles.render(m.styles.dim, pageLabel(m.paginator)))
174		b.WriteString("\n\n")
175		b.WriteString(m.table.View())
176		b.WriteString("\n\n")
177		b.WriteString(m.styles.render(m.styles.statusBar, "j/k navigate  f filter  ←/→ page  enter detail  q quit"))
178		return b.String()
179	}
180	
181	func (m *rootModel) rebuildFilteredRows() {
182		m.filteredRows = m.applyFilter()
183		m.paginator.PerPage = m.pageSize
184		totalPages := m.paginator.SetTotalPages(len(m.filteredRows))
185		if totalPages == 0 {
186			m.paginator.TotalPages = 1
187		}
188		if m.paginator.Page >= m.paginator.TotalPages {
189			m.paginator.Page = max(0, m.paginator.TotalPages-1)
190		}
191		if m.paginator.Page < 0 {
192			m.paginator.Page = 0
193		}
194		m.rebuildTable()
195	}
196	
197	func (m *rootModel) rebuildTable() {
198		pageRows := m.currentPageRows()
199		rows := make([]table.Row, 0, len(pageRows))
200		for _, row := range pageRows {
201			checkpoint := row.CheckpointID
202			if len(checkpoint) > 12 {
203				checkpoint = checkpoint[:12]
204			}
205			rows = append(rows, table.Row{
206				row.CreatedAt.Format("2006-01-02 15:04"),
207				row.Agent,
208				truncate(row.Branch, 24),
209				checkpoint,
210				statusFlag(row.HasSummary),
211				statusFlag(row.HasFacets),
212				strconv.Itoa(row.TotalTokens),
213				strconv.Itoa(row.TurnCount),
214			})
215		}
216		m.table.SetRows(rows)
217		if len(rows) == 0 {
218			m.table.SetCursor(0)
219			return
220		}
221		if m.table.Cursor() >= len(rows) {
222			m.table.SetCursor(len(rows) - 1)
223		}
224	}
225	
226	func (m rootModel) selectedRow() *insightsdb.SessionRow {
227		rows := m.currentPageRows()
228		idx := m.table.Cursor()
229		if idx < 0 || idx >= len(rows) {
230			return nil
231		}
232		return &rows[idx]
233	}
234	
235	func (m rootModel) applyFilter() []insightsdb.SessionRow {
236		filtered := make([]insightsdb.SessionRow, 0, len(m.rows))
237		for _, row := range m.rows {
238			if m.filter == filterMainBranch && row.Branch != "main" {
239				continue
240			}
241			if m.filter == filterCurrentBranch && m.currentBranch != "" && row.Branch != m.currentBranch {
242				continue
243			}
244			filtered = append(filtered, row)
245		}
246		return filtered
247	}
248	
249	func (m rootModel) currentPageRows() []insightsdb.SessionRow {
250		if len(m.filteredRows) == 0 {
251			return nil
252		}
253		start, end := m.paginator.GetSliceBounds(len(m.filteredRows))
254		if start >= len(m.filteredRows) {
255			return nil
256		}
257		if end > len(m.filteredRows) {
258			end = len(m.filteredRows)
259		}
260		return m.filteredRows[start:end]
261	}
262	
263	func (m *rootModel) cycleFilter() {
264		m.filter = (m.filter + 1) % 3
265		m.paginator.Page = 0
266		m.table.SetCursor(0)
267		m.rebuildFilteredRows()
268	}
269	
270	func (m *rootModel) nextPage() {
271		if m.paginator.OnLastPage() {
272			return
273		}
274		m.paginator.NextPage()
275		m.table.SetCursor(0)
276		m.rebuildTable()
277	}
278	
279	func (m *rootModel) prevPage() {
280		if m.paginator.OnFirstPage() {
281			return
282		}
283		m.paginator.PrevPage()
284		m.table.SetCursor(0)
285		m.rebuildTable()
286	}
287	
288	func pageLabel(p paginator.Model) string {
289		return fmt.Sprintf("Page %d/%d", p.Page+1, max(1, p.TotalPages))
290	}
291	
292	func renderFilterChips(styles styles, active branchFilter) string {
293		labels := []struct {
294			filter branchFilter
295			label  string
296		}{
297			{filterCurrentBranch, "Current Branch"},
298			{filterMainBranch, "Main"},
299			{filterAllBranches, "All"},
300		}
301	
302		parts := make([]string, 0, len(labels))
303		for _, item := range labels {
304			text := item.label
305			if item.filter == active {
306				text = "[" + text + "]"
307				parts = append(parts, styles.render(styles.chipActive, text))
308				continue
309			}
310			parts = append(parts, styles.render(styles.chipInactive, text))
311		}
312		return strings.Join(parts, " ")
313	}
314	
315	func (m *rootModel) resize(width, height int) {
316		selectedSessionID := ""
317		if selected := m.selectedRow(); selected != nil {
318			selectedSessionID = selected.SessionID
319		}
320	
321		m.width = width
322		m.height = height
323		m.table.SetWidth(width)
324	
325		tableHeight := max(3, height-rootVerticalChrome)
326		m.table.SetHeight(tableHeight)
327		m.pageSize = max(1, tableHeight-1)
328	
329		m.rebuildFilteredRows()
330		m.restoreSelection(selectedSessionID)
331	}
332	
333	func (m *rootModel) restoreSelection(sessionID string) {
334		if sessionID == "" || len(m.filteredRows) == 0 {
335			return
336		}
337	
338		for idx, row := range m.filteredRows {
339			if row.SessionID != sessionID {
340				continue
341			}
342	
343			m.paginator.Page = idx / m.pageSize
344			m.rebuildTable()
345	
346			cursor := idx % m.pageSize
347			if pageRows := m.currentPageRows(); len(pageRows) > 0 && cursor >= len(pageRows) {
348				cursor = len(pageRows) - 1
349			}
350			m.table.SetCursor(cursor)
351			return
352		}
353	}
