1	package summarytui
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/charmbracelet/bubbles/viewport"
8		tea "github.com/charmbracelet/bubbletea"
9		"github.com/entireio/cli/cmd/entire/cli/insightsdb"
10	)
11	
12	//nolint:recvcheck // bubbletea-style model mixes pointer sizing with value update/view methods
13	type detailModel struct {
14		styles   styles
15		row      insightsdb.SessionRow
16		viewport viewport.Model
17		width    int
18		height   int
19	}
20	
21	func newDetailModel(styles styles, row insightsdb.SessionRow) *detailModel {
22		m := &detailModel{
23			styles: styles,
24			row:    row,
25		}
26		m.setSize(100, 20)
27		return m
28	}
29	
30	func (m detailModel) view() string {
31		var b strings.Builder
32		b.WriteString("SESSION DETAIL\n\n")
33		b.WriteString(m.viewport.View())
34		b.WriteString("\n\nEsc returns to the session table")
35		return b.String()
36	}
37	
38	func (m detailModel) update(msg tea.Msg) (detailModel, tea.Cmd) {
39		var cmd tea.Cmd
40		m.viewport, cmd = m.viewport.Update(msg)
41		return m, cmd
42	}
43	
44	func (m *detailModel) setSize(width, height int) {
45		m.width = width
46		m.height = height
47		m.viewport = viewport.New(width, max(5, height-4))
48		m.viewport.SetContent(m.renderContent())
49	}
50	
51	func (m detailModel) renderContent() string {
52		var b strings.Builder
53	
54		fmt.Fprintf(&b, "Agent: %s\n", m.row.Agent)
55		if m.row.OwnerID != "" {
56			fmt.Fprintf(&b, "Author: %s\n", m.row.OwnerID)
57		}
58		if m.row.OwnerName != "" {
59			fmt.Fprintf(&b, "Author Name: %s\n", m.row.OwnerName)
60		}
61		if m.row.OwnerEmail != "" {
62			fmt.Fprintf(&b, "Author Email: %s\n", m.row.OwnerEmail)
63		}
64		if m.row.Model != "" {
65			fmt.Fprintf(&b, "Model: %s\n", m.row.Model)
66		}
67		fmt.Fprintf(&b, "Session: %s\n", m.row.SessionID)
68		if m.row.Branch != "" {
69			fmt.Fprintf(&b, "Branch: %s\n", m.row.Branch)
70		}
71		fmt.Fprintf(&b, "Checkpoint: %s\n", m.row.CheckpointID)
72		fmt.Fprintf(&b, "Created: %s\n", m.row.CreatedAt.Format("2006-01-02 15:04"))
73		fmt.Fprintf(&b, "Tokens: %d\n", m.row.TotalTokens)
74		fmt.Fprintf(&b, "Turns: %d\n\n", m.row.TurnCount)
75	
76		b.WriteString("Summary\n")
77		b.WriteString(m.renderSummary())
78		b.WriteString("\n\n")
79		b.WriteString("Facets\n")
80		b.WriteString(m.renderFacets())
81		return b.String()
82	}
83	
84	func (m detailModel) renderSummary() string {
85		if !m.row.HasSummary {
86			return "No summary cached"
87		}
88	
89		var b strings.Builder
90		fmt.Fprintf(&b, "Intent: %s\n", fallback(m.row.Intent, "No summary cached"))
91		fmt.Fprintf(&b, "Outcome: %s\n", fallback(m.row.Outcome, "No summary cached"))
92		b.WriteString("Friction:\n")
93		if len(m.row.Friction) == 0 {
94			b.WriteString("  No friction recorded\n")
95		} else {
96			for _, item := range m.row.Friction {
97				fmt.Fprintf(&b, "  - %s\n", item)
98			}
99		}
100	
101		b.WriteString("Learnings:\n")
102		if len(m.row.Learnings) == 0 {
103			b.WriteString("  No learnings recorded\n")
104		} else {
105			for _, item := range m.row.Learnings {
106				if item.Path != "" {
107					fmt.Fprintf(&b, "  - [%s] %s (%s)\n", item.Scope, item.Finding, item.Path)
108					continue
109				}
110				fmt.Fprintf(&b, "  - [%s] %s\n", item.Scope, item.Finding)
111			}
112		}
113		return strings.TrimRight(b.String(), "\n")
114	}
115	
116	func (m detailModel) renderFacets() string {
117		if !m.row.HasFacets {
118			return "No facets cached"
119		}
120	
121		var b strings.Builder
122		b.WriteString("Repeated Instructions:\n")
123		if len(m.row.Facets.RepeatedUserInstructions) == 0 {
124			b.WriteString("  None\n")
125		} else {
126			for _, item := range m.row.Facets.RepeatedUserInstructions {
127				fmt.Fprintf(&b, "  - %s\n", item.Instruction)
128			}
129		}
130	
131		b.WriteString("Missing Context:\n")
132		if len(m.row.Facets.MissingContext) == 0 {
133			b.WriteString("  None\n")
134		} else {
135			for _, item := range m.row.Facets.MissingContext {
136				fmt.Fprintf(&b, "  - %s\n", item.Item)
137			}
138		}
139	
140		b.WriteString("Failure Loops:\n")
141		if len(m.row.Facets.FailureLoops) == 0 {
142			b.WriteString("  None\n")
143		} else {
144			for _, item := range m.row.Facets.FailureLoops {
145				fmt.Fprintf(&b, "  - %s (%d)\n", item.Description, item.Count)
146			}
147		}
148	
149		b.WriteString("Skill Signals:\n")
150		if len(m.row.Facets.SkillSignals) == 0 {
151			b.WriteString("  None\n")
152		} else {
153			for _, item := range m.row.Facets.SkillSignals {
154				fmt.Fprintf(&b, "  - %s\n", item.SkillName)
155			}
156		}
157	
158		b.WriteString("Review-Derived Rules:\n")
159		if len(m.row.Facets.ReviewDerivedRules) == 0 {
160			b.WriteString("  None\n")
161		} else {
162			for _, item := range m.row.Facets.ReviewDerivedRules {
163				fmt.Fprintf(&b, "  - %s\n", item.Rule)
164			}
165		}
166	
167		b.WriteString("Repo Gotchas:\n")
168		if len(m.row.Facets.RepoGotchas) == 0 {
169			b.WriteString("  None\n")
170		} else {
171			for _, item := range m.row.Facets.RepoGotchas {
172				fmt.Fprintf(&b, "  - %s\n", item)
173			}
174		}
175	
176		b.WriteString("Workflow Gaps:\n")
177		if len(m.row.Facets.WorkflowGaps) == 0 {
178			b.WriteString("  None\n")
179		} else {
180			for _, item := range m.row.Facets.WorkflowGaps {
181				fmt.Fprintf(&b, "  - %s\n", item)
182			}
183		}
184	
185		return strings.TrimRight(b.String(), "\n")
186	}
187	
188	func fallback(value, defaultValue string) string {
189		if strings.TrimSpace(value) == "" {
190			return defaultValue
191		}
192		return value
193	}
