1	package summarytui
2	
3	import (
4		"os"
5	
6		"github.com/charmbracelet/bubbles/table"
7		"github.com/charmbracelet/lipgloss"
8		"github.com/entireio/cli/cmd/entire/cli/termstyle"
9	)
10	
11	type styles struct {
12		colorEnabled bool
13		appTitle     lipgloss.Style
14		dim          lipgloss.Style
15		statusBar    lipgloss.Style
16		chipActive   lipgloss.Style
17		chipInactive lipgloss.Style
18		tableHeader  lipgloss.Style
19		tableCell    lipgloss.Style
20		tableSelect  lipgloss.Style
21	}
22	
23	func newStyles() styles {
24		useColor := termstyle.ShouldUseColor(os.Stdout)
25		s := styles{colorEnabled: useColor}
26		if !useColor {
27			return s
28		}
29	
30		amber := lipgloss.Color("214")
31		gray := lipgloss.Color("245")
32	
33		s.appTitle = lipgloss.NewStyle().Bold(true).Foreground(amber)
34		s.dim = lipgloss.NewStyle().Faint(true)
35		s.statusBar = lipgloss.NewStyle().Faint(true)
36		s.chipActive = lipgloss.NewStyle().Bold(true).Foreground(amber)
37		s.chipInactive = lipgloss.NewStyle().Foreground(gray)
38		s.tableHeader = lipgloss.NewStyle().Bold(true).Foreground(amber)
39		s.tableCell = lipgloss.NewStyle()
40		s.tableSelect = lipgloss.NewStyle().Bold(true).Foreground(amber)
41		return s
42	}
43	
44	func (s styles) render(style lipgloss.Style, text string) string {
45		if !s.colorEnabled {
46			return text
47		}
48		return style.Render(text)
49	}
50	
51	func (s styles) tableStyles() table.Styles {
52		ts := table.DefaultStyles()
53		if !s.colorEnabled {
54			return ts
55		}
56		ts.Header = s.tableHeader
57		ts.Cell = s.tableCell
58		ts.Selected = s.tableSelect
59		return ts
60	}
61	
62	func statusFlag(v bool) string {
63		if v {
64			return "yes"
65		}
66		return "no"
67	}
68	
69	func truncate(value string, limit int) string {
70		if limit <= 0 || len(value) <= limit {
71			return value
72		}
73		if limit <= 3 {
74			return value[:limit]
75		}
76		return value[:limit-3] + "..."
77	}
