1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"path/filepath"
9		"strings"
10	
11		"github.com/entireio/cli/cmd/entire/cli/facets"
12		"github.com/entireio/cli/cmd/entire/cli/githubidentity"
13		"github.com/entireio/cli/cmd/entire/cli/insightsdb"
14		"github.com/entireio/cli/cmd/entire/cli/paths"
15		"github.com/entireio/cli/cmd/entire/cli/settings"
16		"github.com/entireio/cli/cmd/entire/cli/summarytui"
17		"github.com/entireio/cli/cmd/entire/cli/termstyle"
18		"github.com/spf13/cobra"
19	)
20	
21	type summaryOptions struct {
22		Last       int
23		Agent      string
24		Branch     string
25		Me         bool
26		OutputJSON bool
27	}
28	
29	const (
30		defaultSummarySessionLimit = 10
31		maxSummaryRecentSessions   = 200
32	)
33	
34	type summarySessionView struct {
35		CheckpointID string               `json:"checkpoint_id"`
36		SessionID    string               `json:"session_id"`
37		Agent        string               `json:"agent"`
38		Model        string               `json:"model,omitempty"`
39		Branch       string               `json:"branch,omitempty"`
40		OwnerID      string               `json:"owner_id,omitempty"`
41		CreatedAt    string               `json:"created_at"`
42		Tokens       int                  `json:"tokens"`
43		Turns        int                  `json:"turns"`
44		HasSummary   bool                 `json:"has_summary"`
45		HasFacets    bool                 `json:"has_facets"`
46		Summary      summaryDetailView    `json:"summary"`
47		Facets       facets.SessionFacets `json:"facets"`
48	}
49	
50	type summaryDetailView struct {
51		Intent    string                   `json:"intent,omitempty"`
52		Outcome   string                   `json:"outcome,omitempty"`
53		Friction  []string                 `json:"friction,omitempty"`
54		Learnings []insightsdb.LearningRow `json:"learnings,omitempty"`
55	}
56	
57	var runSummaryTUI = summarytui.RunWithCurrentBranch
58	var summaryRefreshCacheIfStale = refreshCacheIfStale
59	var summaryBackfillSummaries = backfillSummaries
60	var summaryBackfillFacets = backfillFacets
61	
62	func newSummaryCmd() *cobra.Command {
63		opts := summaryOptions{Last: defaultSummarySessionLimit}
64	
65		cmd := &cobra.Command{
66			Use:   "summary",
67			Short: "Browse source sessions with summaries and facets",
68			RunE: func(cmd *cobra.Command, _ []string) error {
69				ctx := cmd.Context()
70				w := cmd.OutOrStdout()
71	
72				if checkDisabledGuard(ctx, w) {
73					return nil
74				}
75	
76				if !settings.IsSummarizeEnabled(ctx) {
77					fmt.Fprintln(w, "Summarization is required for summary browsing. Enable it in .entire/settings.json:")
78					fmt.Fprintln(w, `  { "strategy_options": { "summarize": { "enabled": true } } }`)
79					return nil
80				}
81	
82				return runSummary(ctx, w, opts)
83			},
84		}
85	
86		cmd.Flags().IntVar(&opts.Last, "last", opts.Last, "number of recent sessions to browse")
87		cmd.Flags().StringVar(&opts.Agent, "agent", "", "filter by agent name")
88		cmd.Flags().StringVar(&opts.Branch, "branch", "", "filter by branch")
89		cmd.Flags().BoolVar(&opts.Me, "me", false, "show only sessions for the active GitHub user")
90		cmd.Flags().BoolVar(&opts.OutputJSON, "json", false, "output sessions as JSON instead of launching the browser")
91		return cmd
92	}
93	
94	func runSummary(ctx context.Context, w io.Writer, opts summaryOptions) error {
95		rows, err := loadSummarySessions(ctx, opts)
96		if err != nil {
97			return err
98		}
99	
100		if opts.OutputJSON {
101			return renderSummaryJSON(w, rows)
102		}
103	
104		if IsAccessibleMode() {
105			renderSummaryText(w, rows)
106			return nil
107		}
108	
109		currentBranch := ""
110		if branch, err := GetCurrentBranch(ctx); err == nil {
111			currentBranch = branch
112		}
113	
114		return runSummaryTUI(ctx, rows, currentBranch)
115	}
116	
117	func loadSummarySessions(ctx context.Context, opts summaryOptions) ([]insightsdb.SessionRow, error) {
118		worktreeRoot, err := paths.WorktreeRoot(ctx)
119		if err != nil {
120			return nil, fmt.Errorf("not in a git repository: %w", err)
121		}
122	
123		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
124		if err != nil {
125			return nil, fmt.Errorf("open insights cache: %w", err)
126		}
127		defer func() { _ = idb.Close() }()
128	
129		outputLimit := normalizedSummarySessionLimit(opts.Last)
130	
131		rows, err := idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
132		if err != nil {
133			return nil, fmt.Errorf("query sessions: %w", err)
134		}
135		if len(rows) == 0 {
136			// First-run fallback: populate the cache if we have nothing local yet.
137			if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
138				return nil, fmt.Errorf("refresh insights cache: %w", err)
139			}
140			rows, err = idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
141			if err != nil {
142				return nil, fmt.Errorf("query sessions after refresh: %w", err)
143			}
144		}
145	
146		summaryBackfillSummaries(ctx, io.Discard, idb, outputLimit)
147		summaryBackfillFacets(ctx, io.Discard, idb, outputLimit)
148	
149		rows, err = idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
150		if err != nil {
151			return nil, fmt.Errorf("query sessions after backfill: %w", err)
152		}
153	
154		ownerID := ""
155		if opts.Me {
156			ownerID, err = githubidentity.ResolveUsername(ctx)
157			if err != nil {
158				return nil, fmt.Errorf("resolve github username: %w", err)
159			}
160		}
161	
162		filtered := make([]insightsdb.SessionRow, 0, len(rows))
163		for _, row := range rows {
164			if opts.Agent != "" && !strings.EqualFold(strings.TrimSpace(row.Agent), strings.TrimSpace(opts.Agent)) {
165				continue
166			}
167			if opts.Branch != "" && !strings.EqualFold(strings.TrimSpace(row.Branch), strings.TrimSpace(opts.Branch)) {
168				continue
169			}
170			if ownerID != "" && !strings.EqualFold(strings.TrimSpace(row.OwnerID), ownerID) {
171				continue
172			}
