187	// backfillSummaries generates summaries for the last N sessions that lack them.
188	// It reads transcripts from the checkpoint store, calls Claude to summarize,
189	// and updates the cache. Errors on individual sessions are logged and skipped.
190	func backfillSummaries(ctx context.Context, w io.Writer, idb *insightsdb.InsightsDB, lastN int) {
191		rows, err := idb.QueryLastNSessions(ctx, lastN)
192		if err != nil {
193			logging.Warn(ctx, "backfillSummaries: query failed", "error", err)
194			return
195		}
196	
197		// Partition sessions into cached vs needing summaries.
198		var unsummarized []insightsdb.SessionRow
199		cached := 0
200		for _, r := range rows {
201			if r.HasSummary {
202				cached++
203			} else {
204				unsummarized = append(unsummarized, r)
205			}
206		}
207	
208		s := termstyle.New(w)
209		if len(unsummarized) == 0 {
210			fmt.Fprintf(w, "%s %d of %d sessions already have summaries\n",
211				s.Render(s.Dim, "i"), cached, len(rows))
212			return
213		}
214	
215		fmt.Fprintf(w, "%s Generating summaries for %d sessions (%d already cached)...\n",
216			s.Render(s.Dim, "i"), len(unsummarized), cached)
217	
218		repo, err := openRepository(ctx)
219		if err != nil {
220			logging.Warn(ctx, "backfillSummaries: open repository failed", "error", err)
221			return
222		}
223		store := checkpoint.NewGitStore(repo)
224		gen := &summarize.ClaudeGenerator{}
225	
226		generated := 0
227		skipped := 0
228	
229		for i, row := range unsummarized {
230			cpID, parseErr := checkpointid.NewCheckpointID(row.CheckpointID)
231			if parseErr != nil {
232				logging.Debug(ctx, "backfillSummaries: invalid checkpoint ID",
233					"checkpoint_id", row.CheckpointID, "error", parseErr)
234				skipped++
235				continue
236			}
237	
238			content, readErr := store.ReadSessionContent(ctx, cpID, row.SessionIndex)
239			if readErr != nil {
240				logging.Debug(ctx, "backfillSummaries: read session content failed",
241					"checkpoint_id", row.CheckpointID, "session_index", row.SessionIndex, "error", readErr)
242				skipped++
243				continue
244			}
245			if len(content.Transcript) == 0 {
246				logging.Debug(ctx, "backfillSummaries: empty transcript",
247					"checkpoint_id", row.CheckpointID, "session_index", row.SessionIndex)
248				skipped++
249				continue
250			}
251	
252			condensed, buildErr := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
253			if buildErr != nil {
254				logging.Debug(ctx, "backfillSummaries: condense transcript failed",
255					"checkpoint_id", row.CheckpointID, "agent", content.Metadata.Agent, "error", buildErr)
256				skipped++
257				continue
258			}
259			if len(condensed) == 0 {
260				logging.Debug(ctx, "backfillSummaries: condensed transcript empty",
261					"checkpoint_id", row.CheckpointID, "agent", content.Metadata.Agent)
262				skipped++
263				continue
264			}
265	
266			input := summarize.Input{
267				Transcript:   condensed,
268				FilesTouched: row.FilesTouched,
269			}
270			summary, genErr := gen.Generate(ctx, input)
271			if genErr != nil {
272				logging.Debug(ctx, "backfillSummaries: generate summary failed",
273					"checkpoint_id", row.CheckpointID, "error", genErr)
274				skipped++
275				continue
276			}
277			if summary == nil {
278				logging.Debug(ctx, "backfillSummaries: nil summary returned",
279					"checkpoint_id", row.CheckpointID)
280				skipped++
281				continue
282			}
283	
284			// Rebuild the row with summary data.
285			content.Metadata.Summary = summary
286			updated := metadataToSessionRow(row.CheckpointID, row.SessionIndex, &content.Metadata)
287	
288			if updateErr := idb.UpdateSessionSummary(ctx, updated); updateErr != nil {
289				logging.Debug(ctx, "backfillSummaries: update session failed",
290					"checkpoint_id", row.CheckpointID, "error", updateErr)
291				skipped++
292				continue
293			}
294	
295			generated++
296			fmt.Fprintf(w, "  %s %s (%d/%d)\n",
297				s.Render(s.Green, "✓"), row.CheckpointID[:12], i+1, len(unsummarized))
298		}
299	
300		if generated > 0 || skipped > 0 {
301			parts := []string{fmt.Sprintf("Generated %d summaries", generated)}
302			if skipped > 0 {
303				parts = append(parts, fmt.Sprintf("skipped %d (set ENTIRE_LOG_LEVEL=DEBUG for details)", skipped))
304			}
305			fmt.Fprintf(w, "  %s\n\n", strings.Join(parts, ", "))
306		}
307	}
