332			CheckpointID: cpID,
333			SessionID:    meta.SessionID,
334			SessionIndex: sessionIndex,
335			Agent:        string(meta.Agent),
336			Model:        meta.Model,
337			Branch:       meta.Branch,
338			OwnerName:    meta.OwnerName,
339			OwnerID:      meta.OwnerID,
340			OwnerEmail:   meta.OwnerEmail,
341			CreatedAt:    meta.CreatedAt,
342		}
343	
344		if meta.TokenUsage != nil {
345			row.InputTokens = meta.TokenUsage.InputTokens + meta.TokenUsage.CacheCreationTokens + meta.TokenUsage.CacheReadTokens
346			row.OutputTokens = meta.TokenUsage.OutputTokens
347			row.TotalTokens = termstyle.TotalTokens(meta.TokenUsage)
348			row.APICallCount = meta.TokenUsage.APICallCount
349		}
350	
351		if meta.SessionMetrics != nil {
352			row.DurationMs = meta.SessionMetrics.DurationMs
353			row.TurnCount = meta.SessionMetrics.TurnCount
354		}
355	
356		if meta.Summary != nil {
357			row.HasSummary = true
358			row.Intent = meta.Summary.Intent
359			row.Outcome = meta.Summary.Outcome
360			row.Friction = meta.Summary.Friction
361	
362			for _, l := range meta.Summary.Learnings.Repo {
363				row.Learnings = append(row.Learnings, insightsdb.LearningRow{Scope: "repo", Finding: l})
364			}
365			for _, l := range meta.Summary.Learnings.Workflow {
366				row.Learnings = append(row.Learnings, insightsdb.LearningRow{Scope: "workflow", Finding: l})
367			}
368			for _, l := range meta.Summary.Learnings.Code {
369				row.Learnings = append(row.Learnings, insightsdb.LearningRow{Scope: "code", Finding: l.Finding, Path: l.Path})
370			}
371		}
372	
373		// Always compute scores — token efficiency and focus work without summaries.
374		// Friction/first-pass default to neutral when no summary exists.
375		data := insights.SessionData{
376			TotalTokens:   row.TotalTokens,
377			FilesCount:    len(meta.FilesTouched),
378			FrictionCount: len(row.Friction),
379			TurnCount:     row.TurnCount,
380			HasSummary:    row.HasSummary,
381		}
382		if meta.Summary != nil {
383			data.OpenItemCount = len(meta.Summary.OpenItems)
384		}
385		breakdown := insights.ScoreSession(data)
386		row.OverallScore = insights.ComputeOverall(breakdown)
387		row.ScoreTokenEff = breakdown.TokenEfficiency
388		row.ScoreFirstPass = breakdown.FirstPassSuccess
389		row.ScoreFriction = breakdown.FrictionScore
390		row.ScoreFocus = breakdown.FocusScore
391	
392		row.FilesTouched = meta.FilesTouched
393		return row
394	}
